"""Turn uploaded bytes (PDF/TXT) into per-page text."""
import io
from dataclasses import dataclass
from pathlib import PurePath

from pypdf import PdfReader
from pypdf.errors import PyPdfError


class DocumentError(ValueError):
    """The uploaded file cannot be used; the message is safe to show a user."""


@dataclass(frozen=True)
class Page:
    number: int  # 1-based
    text: str


@dataclass(frozen=True)
class Document:
    name: str
    pages: list[Page]


def load_document(filename: str, data: bytes) -> Document:
    name = PurePath(filename).name
    ext = PurePath(name).suffix.lower()
    if ext == ".txt":
        pages = _load_txt(data)
    elif ext == ".pdf":
        pages = _load_pdf(name, data)
    else:
        raise DocumentError(f"{name}: unsupported file type '{ext}' (use .pdf or .txt)")
    pages = [p for p in pages if p.text.strip()]
    if not pages:
        raise DocumentError(f"{name}: no extractable text (scanned PDFs need OCR, which is not supported)")
    return Document(name=name, pages=pages)


def _load_txt(data: bytes) -> list[Page]:
    try:
        text = data.decode("utf-8-sig")
    except UnicodeDecodeError:
        text = data.decode("cp1252", errors="replace")
    return [Page(1, text)]


def _load_pdf(name: str, data: bytes) -> list[Page]:
    try:
        reader = PdfReader(io.BytesIO(data))
        if reader.is_encrypted:
            raise DocumentError(f"{name}: encrypted PDFs are not supported")
        return [Page(i, page.extract_text() or "") for i, page in enumerate(reader.pages, start=1)]
    except DocumentError:
        raise
    except (PyPdfError, ValueError, OSError, KeyError) as exc:
        raise DocumentError(f"{name}: could not read PDF ({type(exc).__name__})") from exc
EOF
cat > rag/chunking.py <<'EOF'
"""Paragraph-aware chunking with a small character overlap."""
import re


def chunk_text(text: str, size: int = 800, overlap: int = 100) -> list[str]:
    """Pack paragraphs into chunks of about `size` chars.

    Paragraphs are kept whole when they fit; longer ones are split on whitespace.
    Each chunk after the first starts with the last `overlap` chars (word-aligned)
    of the previous one, so a chunk may reach size + overlap.
    """
    if size <= 0 or not 0 <= overlap < size:
        raise ValueError("require size > 0 and 0 <= overlap < size")
    units: list[str] = []
    for para in re.split(r"\n\s*\n", text):
        para = " ".join(para.split())
        if para:
            units.extend(_split_long(para, size))

    chunks: list[str] = []
    current = ""
    for unit in units:
        if current and len(current) + 1 + len(unit) > size:
            chunks.append(current)
            current = (_tail(current, overlap) + " " + unit).strip()
        else:
            current = f"{current} {unit}".strip() if current else unit
    if current:
        chunks.append(current)
    return chunks


def _split_long(para: str, size: int) -> list[str]:
    if len(para) <= size:
        return [para]
    out, current = [], ""
    for word in para.split(" "):
        while len(word) > size:  # unbroken string: hard split
            if current:
                out.append(current)
                current = ""
            out.append(word[:size])
            word = word[size:]
        if current and len(current) + 1 + len(word) > size:
            out.append(current)
            current = word
        else:
            current = f"{current} {word}".strip() if current else word
    if current:
        out.append(current)
    return out


def _tail(text: str, overlap: int) -> str:
    if overlap <= 0 or len(text) <= overlap:
        return text if overlap > 0 else ""
    tail = text[-overlap:]
    cut = tail.find(" ")
    return tail[cut + 1:] if cut != -1 else tail
EOF
cat > rag/embeddings.py <<'EOF'
"""Embedder interface plus the local FastEmbed implementation."""
from typing import Protocol

import numpy as np


class Embedder(Protocol):
    def embed_documents(self, texts: list[str]) -> np.ndarray: ...
    def embed_query(self, text: str) -> np.ndarray: ...


def _normalize(m: np.ndarray) -> np.ndarray:
    m = np.asarray(m, dtype=np.float32)
    norms = np.linalg.norm(m, axis=-1, keepdims=True)
    return m / np.where(norms == 0, 1, norms)


class FastEmbedEmbedder:
    """Local ONNX embeddings. The model is downloaded on first use (needs huggingface.co)."""

    def __init__(self, model_name: str = "BAAI/bge-small-en-v1.5"):
        self.model_name = model_name
        self._model = None

    def _get(self):
        if self._model is None:
            from fastembed import TextEmbedding  # lazy: import and download only when used
            self._model = TextEmbedding(self.model_name)
        return self._model

    def embed_documents(self, texts: list[str]) -> np.ndarray:
        return _normalize(np.array(list(self._get().embed(texts))))

    def embed_query(self, text: str) -> np.ndarray:
        # query_embed applies the model's query instruction prefix where one exists
        return _normalize(np.array(list(self._get().query_embed(text)))[0])
EOF
cat > rag/store.py <<'EOF'
"""In-memory collection: chunk records plus a normalized embedding matrix."""
import uuid
from dataclasses import dataclass, field

import numpy as np


@dataclass(frozen=True)
class Chunk:
    id: int  # index within the collection
    doc: str
    page: int
    text: str


@dataclass(frozen=True)
class Hit:
    chunk: Chunk
    score: float  # cosine similarity


@dataclass
class Collection:
    chunks: list[Chunk]
    vectors: np.ndarray  # (n_chunks, dim), L2-normalized
    id: str = field(default_factory=lambda: uuid.uuid4().hex[:12])

    @property
    def doc_names(self) -> list[str]:
        return sorted({c.doc for c in self.chunks})

    def search(self, query_vec: np.ndarray, k: int) -> list[Hit]:
        if not self.chunks or k <= 0:
            return []
        scores = self.vectors @ query_vec
        top = np.argsort(-scores)[:k]
        return [Hit(self.chunks[i], float(scores[i])) for i in top]
EOF
cat > rag/pipeline.py <<'EOF'
"""Ingest documents into a Collection and retrieve chunks for a question."""
from dataclasses import dataclass

import numpy as np

from .chunking import chunk_text
from .config import Settings
from .embeddings import Embedder
from .loaders import DocumentError, load_document
from .store import Chunk, Collection, Hit


def build_collection(files: list[tuple[str, bytes]], embedder: Embedder, settings: Settings) -> Collection:
    """files: (filename, raw bytes). Raises DocumentError naming the first bad file."""
    if not files:
        raise DocumentError("no files provided")
    limit = settings.max_file_mb * 1024 * 1024
    chunks: list[Chunk] = []
    for filename, data in files:
        if len(data) > limit:
            raise DocumentError(f"{filename}: larger than {settings.max_file_mb} MB")
        doc = load_document(filename, data)
        for page in doc.pages:
            for text in chunk_text(page.text, settings.chunk_size, settings.chunk_overlap):
                chunks.append(Chunk(len(chunks), doc.name, page.number, text))
    vectors = embedder.embed_documents([c.text for c in chunks])
    return Collection(chunks=chunks, vectors=np.asarray(vectors, dtype=np.float32))


@dataclass(frozen=True)
class Retrieval:
    hits: list[Hit]
    min_score: float

    @property
    def top_score(self) -> float:
        return self.hits[0].score if self.hits else 0.0

    @property
    def passes_gate(self) -> bool:
        """Cheap pre-filter only. Passing does NOT mean the chunks answer the question;
        the LLM (stage 2) must still judge sufficiency."""
        return self.top_score >= self.min_score


def retrieve(collection: Collection, question: str, embedder: Embedder, settings: Settings) -> Retrieval:
    hits = collection.search(embedder.embed_query(question), settings.top_k)
    return Retrieval(hits=hits, min_score=settings.min_score)
EOF

